<tr><td>A</td><td>PAGE</td><td>IX</td><td>GRANT</td></tr>
<tr><td>A</td><td>KEY</td><td>X</td><td>GRANT</td></tr>
<tr><td>B</td><td>OBJECT</td><td>IS</td><td>GRANT</td></tr>
<tr><td>B</td><td>PAGE</td><td>IS</td><td>GRANT</td></tr>
<tr><td>B</td><td>KEY</td><td>S</td><td>WAIT</td></tr>
