<pre><code class="language-sql">-- Trên PostgreSQL y hệt
CREATE TABLE DoanhThu (thang CHAR(7) NOT NULL CONSTRAINT pk_doanhthu PRIMARY KEY, tien INT NOT NULL);
INSERT INTO DoanhThu VALUES ('2026-01', 120), ('2026-02', 90), ('2026-03', 150),
                            ('2026-04', 150), ('2026-05', 180), ('2026-06', 135);
-- Luỹ kế từ đầu năm và trung bình trượt 3 tháng
SELECT thang, tien,
       SUM(tien) OVER (ORDER BY thang ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS luy_ke,
       CAST(AVG(tien * 1.0) OVER (ORDER BY thang ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS DECIMAL(6,1)) AS tb_truot_3
FROM DoanhThu
ORDER BY thang;</code></pre>
