<pre><code class="language-sql">-- Trên PostgreSQL y hệt
-- "Nhân viên có tham gia ít nhất một dự án": JOIN nhân bản dòng, EXISTS/IN thì không
SELECT (SELECT COUNT(*) FROM tblEmployee AS e JOIN tblWorksOn AS w ON w.empSSN = e.empSSN) AS dung_join,
       (SELECT COUNT(*) FROM tblEmployee AS e
         WHERE EXISTS (SELECT 1 FROM tblWorksOn AS w WHERE w.empSSN = e.empSSN))            AS dung_exists,
       (SELECT COUNT(*) FROM tblEmployee AS e
         WHERE e.empSSN IN (SELECT w.empSSN FROM tblWorksOn AS w))                          AS dung_in;</code></pre>
