<pre><code class="language-sql">ALTER TABLE khach_hang ADD COLUMN so_dien_thoai VARCHAR(15);             -- 1. cho phép NULL
UPDATE khach_hang SET so_dien_thoai = '09000000' || id
WHERE so_dien_thoai IS NULL;                                            -- 2. điền dữ liệu
ALTER TABLE khach_hang ALTER COLUMN so_dien_thoai SET NOT NULL;          -- 3. siết lại
ALTER TABLE khach_hang RENAME COLUMN ten TO ho_ten;
-- VIEW vẫn sống: PostgreSQL gắn view vào cột chứ không vào tên
SELECT * FROM v_khach ORDER BY id;
SELECT pg_get_viewdef('v_khach') AS dinh_nghia_view_bay_gio;</code></pre>
