<tr><td>A</td><td>1</td><td>500</td><td>500</td><td>500</td></tr>
<tr><td>A</td><td>2</td><td>-200</td><td>300</td><td>300</td></tr>
<tr><td>A</td><td>3</td><td>300</td><td>600</td><td>500</td></tr>
<tr><td>A</td><td>4</td><td>-100</td><td>500</td><td>500</td></tr>
<tr><td>B</td><td>5</td><td>1000</td><td>1000</td><td>1000</td></tr>
