<pre><code class="language-sql">-- PostgreSQL: cột boolean, AVG((…)::int) và FILTER
CREATE TABLE NguoiDung (id INT NOT NULL CONSTRAINT pk_nguoidung PRIMARY KEY, bi_cam BOOLEAN NOT NULL);
CREATE TABLE Chuyen (id INT NOT NULL CONSTRAINT pk_chuyen PRIMARY KEY, khach INT NOT NULL, tai_xe INT NOT NULL,
                     trang_thai VARCHAR(10) NOT NULL, ngay DATE NOT NULL);
INSERT INTO NguoiDung VALUES (1, false), (2, true), (3, false), (10, false), (11, false), (12, true);
INSERT INTO Chuyen VALUES
 (1, 1, 10, 'XONG', '2026-09-01'), (2, 2, 11, 'HUY', '2026-09-01'), (3, 3, 12, 'XONG', '2026-09-01'),
 (4, 1, 11, 'HUY', '2026-09-01'), (5, 1, 10, 'XONG', '2026-09-02'), (6, 3, 11, 'HUY', '2026-09-02'),
 (7, 2, 10, 'XONG', '2026-09-02'), (8, 3, 10, 'XONG', '2026-09-03');
SELECT c.ngay, COUNT(*) AS so_chuyen, COUNT(*) FILTER (WHERE c.trang_thai = 'HUY') AS so_huy,
       ROUND(AVG((c.trang_thai = 'HUY')::int), 2) AS ty_le_huy
FROM Chuyen AS c
JOIN NguoiDung AS k ON k.id = c.khach AND NOT k.bi_cam
JOIN NguoiDung AS t ON t.id = c.tai_xe AND NOT t.bi_cam
GROUP BY c.ngay
ORDER BY c.ngay;</code></pre>
